    private val byId: Map<String, Pic> by lazy { ALL.associateBy { it.id } }
    fun find(id: String?): Pic? = if (id.isNullOrEmpty()) null else byId[id]

    /** The picture's steps, or null when the string is not one (pure: the tests read every picture through it). */
    fun parse(d: String): List<Op>? {
        val t = d.trim().split(' ').filter { it.isNotEmpty() }
        val out = ArrayList<Op>()
        var i = 0
        while (i < t.size) {
            val c = t[i].singleOrNull() ?: return null
            val need = when (c) { 'M', 'L' -> 2; 'C' -> 6; 'Z' -> 0; else -> return null }
            val n = FloatArray(need)
            for (k in 0 until need) n[k] = t.getOrNull(i + 1 + k)?.toFloatOrNull() ?: return null
            out += Op(c, n)
            i += 1 + need
        }
        return if (out.isEmpty() || out.first().c != 'M') null else out
    }

    fun toPath(ops: List<Op>): Path {
        val p = Path()
        for (o in ops) when (o.c) {
            'M' -> p.moveTo(o.n[0], o.n[1])
            'L' -> p.lineTo(o.n[0], o.n[1])
            'C' -> p.cubicTo(o.n[0], o.n[1], o.n[2], o.n[3], o.n[4], o.n[5])
            else -> p.close()
        }
        return p
    }
}

/** A profile's picture drawn in [tint], [size] across (nothing when the name is unknown). */
@Composable
internal fun WhoGlyph(pic: String, tint: Color, size: Dp, modifier: Modifier = Modifier) {
    val path = remember(pic) { WhoPics.find(pic)?.let { WhoPics.parse(it.path) }?.let { WhoPics.toPath(it) } } ?: return
    Canvas(modifier.size(size)) {
        val s = this.size.minDimension / 24f
        scale(s, s, pivot = Offset.Zero) { drawPath(path, tint) }
    }
}
